def check_document(parsed, constraints, rel_types, name_to_id):
    """Check violations for one document parsed output.

    v2: ET violations counted per unique entity (text+type dedup).
    """
    entities = parsed.get("entities", [])
    relations = parsed.get("relations", [])

    violations = {
        "entity_type": [],
        "relation_vocabulary": [],
        "domain_range": [],
        "cross_field_consistency": [],
    }
    fuzzy_matches = 0

    seen_entities = {}
    for ent in entities:
        text = ent.get("text", "?")
        etype = ent.get("type", "")
        norm = normalize_entity_type(etype)
        key = (text.lower().strip(), norm)
        if key not in seen_entities:
            seen_entities[key] = {"entity": text, "invalid_type": etype}

    for rel in relations:
        head = rel.get("head", "")
        tail = rel.get("tail", "")
        h_type = rel.get("head_type", "")
        t_type = rel.get("tail_type", "")
        if head and h_type:
            norm_h = normalize_entity_type(h_type)
            key = (head.lower().strip(), norm_h)
            if key not in seen_entities:
                seen_entities[key] = {"entity": head, "invalid_type": h_type}
        if tail and t_type:
            norm_t = normalize_entity_type(t_type)
            key = (tail.lower().strip(), norm_t)
            if key not in seen_entities:
                seen_entities[key] = {"entity": tail, "invalid_type": t_type}

    for (_, norm_type), info in seen_entities.items():
        if norm_type not in VALID_ENTITY_TYPES:
            violations["entity_type"].append(info)

    entity_type_assignments = defaultdict(set)

    for rel in relations:
        head = rel.get("head", "")
        tail = rel.get("tail", "")
        h_type = rel.get("head_type", "")
        t_type = rel.get("tail_type", "")
        rel_type = rel.get("type", "")

        if head and h_type:
            entity_type_assignments[head.lower()].add(normalize_entity_type(h_type))
        if tail and t_type:
            entity_type_assignments[tail.lower()].add(normalize_entity_type(t_type))

        matched_pid, matched_name, is_fuzzy = normalize_relation(rel_type, rel_types, name_to_id)

        if matched_pid is None:
            violations["relation_vocabulary"].append({
                "head": head,
                "tail": tail,
                "relation": rel_type,
                "reason": "unknown_relation_type",
            })
            continue

        if is_fuzzy:
            fuzzy_matches += 1

        if matched_pid in constraints.get("relation_constraints", {}):
            valid_pairs = constraints["relation_constraints"][matched_pid]["valid_pairs"]
            pair = [normalize_entity_type(h_type), normalize_entity_type(t_type)]
            if pair not in valid_pairs:
                violations["domain_range"].append({
                    "head": head,
                    "tail": tail,
                    "relation": rel_type,
                    "relation_id": matched_pid,
                    "matched_name": matched_name,
                    "head_type": h_type,
                    "tail_type": t_type,
                })

    for entity_name, types in entity_type_assignments.items():
        if len(types) > 1:
            violations["cross_field_consistency"].append({
                "entity": entity_name,
                "conflicting_types": sorted(types),
            })

    return violations, fuzzy_matches
